INSERT INTO wiki_pages (path,title,summary,commit_sha,content_sha,updated_at,metadata_json) VALUES ('wiki/sources/trassenanmeldung-im-gelegenheitsverkehr.md','Trassenanmeldung im Gelegenheitsverkehr','Bei Anmeldungen zum Gelegenheitsverkehr handelt es sich um: - Anmeldungen außerhalb des Netzfahrplans bzw. außerhalb der Fristen des Netzfahrplans - Änderungsanmeldungen zu Trassen des Netzfahrplans - Änderungsanmeldungen zu Trassen des Gelegenheitsverkehrs Trassen für den Gelegenheitsverkehr werden im Rahmen der vorhandenen freien Kapazitäten der Infrastruk','bootstrap:f8dfc1a873a48ca396ea046a5cc9add01212dc42661928708329bb77e6998fff','95fdd6693e3d4243ca1983fd0f0b90984ad70d9748685226013bb00705849ee0','2026-08-08T12:35:15Z','{"bootstrap":true,"canonical_url":"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/gelegenheitsverkehr-10907274","license":"unknown","origin_page_url":"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/gelegenheitsverkehr-10907274","source_id":"src_a84dc841278f39fe70cc","source_version_id":"sv_778cf7ecc04d4171056d4583"}') ON CONFLICT(path) DO UPDATE SET title=excluded.title,summary=excluded.summary,commit_sha=excluded.commit_sha,content_sha=excluded.content_sha,updated_at=excluded.updated_at,metadata_json=excluded.metadata_json;
