INSERT INTO wiki_pages (path,title,summary,commit_sha,content_sha,updated_at,metadata_json) VALUES ('wiki/sources/trassenanmeldung-im-netzfahrplan.md','Trassenanmeldung im Netzfahrplan','Die DB InfraGO AG konstruiert die Trassen des Netzfahrplans auf der Basis von Trassenanmeldungen. Um eine hochwertige, den Ansprüchen der Kund:innen genügende Trasse zu konstruieren, bedarf es detaillierter Angaben wie zum Beispiel dem vorgesehenen Fahrzeugeinsatz, dem gewünschten Verkehrszeitraum und dem geplanten Fahrtverlauf. Die jeweilige Trassenanmeldef','bootstrap:f8dfc1a873a48ca396ea046a5cc9add01212dc42661928708329bb77e6998fff','ad1cde1010da610e57c6e4758d8c5a7b7cbb875bec8ca10e3bed5d7055fb20c1','2026-08-08T12:35:15Z','{"bootstrap":true,"canonical_url":"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/netzfahrplan-11861526","license":"unknown","origin_page_url":"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/netzfahrplan-11861526","source_id":"src_55f3c19c14f539666c5f","source_version_id":"sv_5d5a297063e24f3830a5c3dc"}') ON CONFLICT(path) DO UPDATE SET title=excluded.title,summary=excluded.summary,commit_sha=excluded.commit_sha,content_sha=excluded.content_sha,updated_at=excluded.updated_at,metadata_json=excluded.metadata_json;
